SELECT 
	RV.MERCADO AS RV_MERCADO,RV.NEMO AS RV_NEMO,PRE_PULT_TR AS RV_PRE_PULT_TR,PRE_ULT_TR AS RV_PRE_ULT_TR,CATEGORIA AS RV_CATEGORIA,IND_CARTERA AS RV_IND_CARTERA,IND_EXCLUIDA AS RV_IND_EXCLUIDA,
	AUT_VT_CORTO AS RV_AUT_VT_CORTO,TENDEN_VT_CORTO AS RV_TENDEN_VT_CORTO,IND_LIQ_DCV AS RV_IND_LIQ_DCV,COALESCE(BOLSA,'BCS') AS RV_BOLSA,MONEDA AS RV_MONEDA,AUT_OD_BLOQUE AS RV_AUT_OD_BLOQUE,COD_RUBRO AS RV_COD_RUBRO,
	PRE_APE_DI_AC AS RV_PRE_APE_DI_AC,PRE_MAY_52SEM AS RV_PRE_MAY_52SEM,PRE_MEN_52SEM AS RV_PRE_MEN_52SEM,PRE_CIE_7DIAS AS RV_PRE_CIE_7DIAS,PRE_CIE_30DIAS AS RV_PRE_CIE_30DIAS,PRE_CIE_52SEM AS RV_PRE_CIE_52SEM,
	RENT_7DIAS AS RV_RENT_7DIAS,RENT_30DIAS AS RV_RENT_30DIAS,RENT_52SEM AS RV_RENT_52SEM,DIVIDEND_YIELD AS RV_DIVIDEND_YIELD,BETA_90DIAS AS RV_BETA_90DIAS,CODIGO_ISIN AS RV_CODIGO_ISIN,P_IPSA AS RV_P_IPSA,
	P_IGPA AS RV_P_IGPA,P_INTER_10 AS RV_P_INTER_10,ACCIONES_EQ AS RV_ACCIONES_EQ,VALOR_EQ AS RV_VALOR_EQ,NON_FFLOAT AS RV_NON_FFLOAT,SECTOR AS RV_SECTOR,PRE_CIE_TEORICO AS RV_PRE_CIE_TEORICO,
	BOLSA_EX AS RV_BOLSA_EX,MONEDA_EX AS RV_MONEDA_EX,PAIS_EMISOR AS RV_PAIS_EMISOR,TIPO_INSTRU AS RV_TIPO_INSTRU,VOL_52SEM AS RV_VOL_52SEM,LISTA AS RV_LISTA,

	CF.NEMO AS CF_NEMO,LOTE_PADRON AS CF_LOTE_PADRON,CESA_PAGO AS CF_CESA_PAGO,COD_OFI AS CF_COD_OFI,COD_OFI_SASA AS CF_COD_OFI_SASA,COND_COD_DI_AC_001 AS CF_COND_COD_DI_AC_001,COND_COD_DI_AC_002 AS CF_COND_COD_DI_AC_002,
	COND_COD_DI_AC_003 AS CF_COND_COD_DI_AC_003,COND_COD_DI_AC_004 AS CF_COND_COD_DI_AC_004,COND_COD_DI_AC_005 AS CF_COND_COD_DI_AC_005,COND_COD_DI_AC_006 AS CF_COND_COD_DI_AC_006,COND_COD_DI_AC_007 AS CF_COND_COD_DI_AC_007,
	COND_COD_DI_AC_008 AS CF_COND_COD_DI_AC_008,COND_COD_DI_AC_009 AS CF_COND_COD_DI_AC_009,COND_COD_DI_AC_010 AS CF_COND_COD_DI_AC_010,COND_COD_OFI_001 AS CF_COND_COD_OFI_001,COND_COD_OFI_002 AS CF_COND_COD_OFI_002,
	COND_COD_OFI_003 AS CF_COND_COD_OFI_003,COND_COD_OFI_004 AS CF_COND_COD_OFI_004,COND_COD_OFI_005 AS CF_COND_COD_OFI_005,COND_COD_OFI_006 AS CF_COND_COD_OFI_006,COND_COD_OFI_007 AS CF_COND_COD_OFI_007,
	COND_COD_OFI_008 AS CF_COND_COD_OFI_008,COND_COD_OFI_009 AS CF_COND_COD_OFI_009,COND_COD_OFI_010 AS CF_COND_COD_OFI_010,COND_DIS_AN_AN AS CF_COND_DIS_AN_AN,COND_DIS_DI_AN AS CF_COND_DIS_DI_AN,
	COND_DIS_DI_AC AS CF_COND_DIS_DI_AC,COND_DIS_ME_AN AS CF_COND_DIS_ME_AN,COND_DIS_OFI AS CF_COND_DIS_OFI,COND_DIS_SE_AN AS CF_COND_DIS_SE_AN,COND_DIS_SN_AN AS CF_COND_DIS_SN_AN,
	CUO_INSCRIP AS CF_CUO_INSCRIP,DIVIDENDOS AS CF_DIVIDENDOS,DIAS_TR_ME_AC AS CF_DIAS_TR_ME_AC,DIAS_TR_SE_AC AS CF_DIAS_TR_SE_AC,DIAS_TR_AN_AC AS CF_DIAS_TR_AN_AC,DIAS_TR_TR_AC AS CF_DIAS_TR_TR_AC,
	CF.EMISOR AS CF_EMISOR,CF.ESTADO AS CF_ESTADO,FEC_EST_SIT AS CF_FEC_EST_SIT,FEC_FIJ_CIE AS CF_FEC_FIJ_CIE,FEC_INSCRIP AS CF_FEC_INSCRIP,FEC_ULT_TR AS CF_FEC_ULT_TR,HORA_FIJ_CIE AS CF_HORA_FIJ_CIE,
	IND_AJU_VC_ULT_TR AS CF_IND_AJU_VC_ULT_TR,IND_SIT_ESP AS CF_IND_SIT_ESP,IND_HISBUR AS CF_IND_HISBUR,IND_INSTRU AS CF_IND_INSTRU,INVER_ME AS CF_INVER_ME,INVER_SE AS CF_INVER_SE,INVER_AN AS CF_INVER_AN,
	LIQUIDA AS CF_LIQUIDA,MONTO_AN_AC AS CF_MONTO_AN_AC,MONTO_AN_AN AS CF_MONTO_AN_AN,MONTO_DI_AC AS CF_MONTO_DI_AC,MONTO_DI_AN AS CF_MONTO_DI_AN,MONTO_ME_AC AS CF_MONTO_ME_AC,MONTO_ME_AN AS CF_MONTO_ME_AN,
	MONTO_PMED_DI_AC AS CF_MONTO_PMED_DI_AC,MONTO_PMED_SN_AC AS CF_MONTO_PMED_SN_AC,MONTO_PMED_ME_AC AS CF_MONTO_PMED_ME_AC,MONTO_PMED_SE_AC AS CF_MONTO_PMED_SE_AC,MONTO_PMED_AN_AC AS CF_MONTO_PMED_AN_AC,MONTO_PROM_UF_3M AS CF_MONTO_PROM_UF_3M,
	MONTO_SE_AC AS CF_MONTO_SE_AC,MONTO_SE_AN AS CF_MONTO_SE_AN,MONTO_SN_AC AS CF_MONTO_SN_AC,MONTO_SN_AN AS CF_MONTO_SN_AN,NAA AS CF_NAA,CF.NEMO_SASA AS CF_NEMO_SASA,CF.RAZON_SOCIAL AS CF_RAZON_SOCIAL,NUM_DEC_PRE AS CF_NUM_DEC_PRE,
	CUO_CIR_ME_AC AS CF_CUO_CIR_ME_AC,CUO_31DIC AS CF_CUO_31DIC,NUM_MES_UTI AS CF_NUM_MES_UTI,NUM_NEG_AN_AC AS CF_NUM_NEG_AN_AC,NUM_NEG_AN_AN AS CF_NUM_NEG_AN_AN,NUM_NEG_DI_AC AS CF_NUM_NEG_DI_AC,NUM_NEG_DI_AN AS CF_NUM_NEG_DI_AN,
	NUM_NEG_ME_AC AS CF_NUM_NEG_ME_AC,NUM_NEG_ME_AN AS CF_NUM_NEG_ME_AN,NUM_NEG_SE_AC AS CF_NUM_NEG_SE_AC,NUM_NEG_SE_AN AS CF_NUM_NEG_SE_AN,NUM_NEG_SN_AC AS CF_NUM_NEG_SN_AC,NUM_NEG_SN_AN AS CF_NUM_NEG_SN_AN,NUM_REDON AS CF_NUM_REDON,
	PATRI_AJU AS CF_PATRI_AJU,PATRI_CON AS CF_PATRI_CON,PATRI_AN_AC AS CF_PATRI_AN_AC,PATRI_AN_AN AS CF_PATRI_AN_AN,PATRI_ME_AC AS CF_PATRI_ME_AC,PATRI_ME_AN AS CF_PATRI_ME_AN,PATRI_NEG AS CF_PATRI_NEG,
	PATRI_SE_AC AS CF_PATRI_SE_AC,PATRI_SE_AN AS CF_PATRI_SE_AN,PRESEN_AN_AC AS CF_PRESEN_AN_AC,PRESEN_AN_AN AS CF_PRESEN_AN_AN,PRESEN_DIN AS CF_PRESEN_DIN,PRESEN_ME_AC AS CF_PRESEN_ME_AC,PRESEN_ME_AN AS CF_PRESEN_ME_AN,
	PRESEN_SE_AC AS CF_PRESEN_SE_AC,PRESEN_SE_AN AS CF_PRESEN_SE_AN,PRESEN_PRO_12_M AS CF_PRESEN_PRO_12_M,PRESEN_PRO_1_T AS CF_PRESEN_PRO_1_T,PRESEN_PRO_2_T AS CF_PRESEN_PRO_2_T,PRESEN_PRO_3_T AS CF_PRESEN_PRO_3_T,PRESEN_PRO_4_T AS CF_PRESEN_PRO_4_T,PRE_CIE_AN_AN AS CF_PRE_CIE_AN_AN,
	PRE_CIE_DI_AC AS CF_PRE_CIE_DI_AC,PRE_CIE_DI_AN AS CF_PRE_CIE_DI_AN,PRE_CIE_ME_AN AS CF_PRE_CIE_ME_AN,PRE_CIE_OFI AS CF_PRE_CIE_OFI,PRE_CIE_PEN AS CF_PRE_CIE_PEN,PRE_CIE_SE_AN AS CF_PRE_CIE_SE_AN,PRE_CIE_SN_AN AS CF_PRE_CIE_SN_AN,
	PRE_MAY_AN_AC AS CF_PRE_MAY_AN_AC,PRE_MAY_AN_AN AS CF_PRE_MAY_AN_AN,PRE_MAY_DI_AC AS CF_PRE_MAY_DI_AC,PRE_MAY_DI_AN AS CF_PRE_MAY_DI_AN,PRE_MAY_ME_AC AS CF_PRE_MAY_ME_AC,PRE_MAY_ME_AN AS CF_PRE_MAY_ME_AN,PRE_MAY_SE_AC AS CF_PRE_MAY_SE_AC,
	PRE_MAY_SE_AN AS CF_PRE_MAY_SE_AN,PRE_MAY_SN_AC AS CF_PRE_MAY_SN_AC,PRE_MAY_SN_AN AS CF_PRE_MAY_SN_AN,PRE_MED_AN_AC AS CF_PRE_MED_AN_AC,PRE_MED_AN_AN AS CF_PRE_MED_AN_AN,PRE_MED_DI_AC AS CF_PRE_MED_DI_AC,
	PRE_MED_DI_AN AS CF_PRE_MED_DI_AN,PRE_MED_ME_AC AS CF_PRE_MED_ME_AC,PRE_MED_ME_AN AS CF_PRE_MED_ME_AN,PRE_MED_ULT_TR AS CF_PRE_MED_ULT_TR,PRE_MED_SE_AC AS CF_PRE_MED_SE_AC,
	PRE_MED_SE_AN AS CF_PRE_MED_SE_AN,PRE_MED_SN_AC AS CF_PRE_MED_SN_AC,PRE_MED_SN_AN AS CF_PRE_MED_SN_AN,PRE_MEN_AN_AC AS CF_PRE_MEN_AN_AC,PRE_MEN_AN_AN AS CF_PRE_MEN_AN_AN,PRE_MEN_DI_AC AS CF_PRE_MEN_DI_AC,
	PRE_MEN_DI_AN AS CF_PRE_MEN_DI_AN,PRE_MEN_ME_AC AS CF_PRE_MEN_ME_AC,PRE_MEN_ME_AN AS CF_PRE_MEN_ME_AN,PRE_MEN_SE_AC AS CF_PRE_MEN_SE_AC,PRE_MEN_SE_AN AS CF_PRE_MEN_SE_AN,
	PRE_MEN_SN_AC AS CF_PRE_MEN_SN_AC,PRE_MEN_SN_AN AS CF_PRE_MEN_SN_AN,REL_BOL_LIB AS CF_REL_BOL_LIB,REL_PRE_DIV AS CF_REL_PRE_DIV,REL_PRE_UTI AS CF_REL_PRE_UTI,RENT_AN_AC AS CF_RENT_AN_AC,
	RENT_AN_AN AS CF_RENT_AN_AN,RENT_ME_AC AS CF_RENT_ME_AC,RENT_ME_AN AS CF_RENT_ME_AN,RENT_SE_AC AS CF_RENT_SE_AC,RENT_SE_AN AS CF_RENT_SE_AN,TENDEN_DI_AC AS CF_TENDEN_DI_AC,
	TIPO_ENT AS CF_TIPO_ENT,PRE_ULT_DI_AC AS CF_PRE_ULT_DI_AC,UNI_PMED_DI_AC AS CF_UNI_PMED_DI_AC,UNI_PMED_SN_AC AS CF_UNI_PMED_SN_AC,UNI_PMED_ME_AC AS CF_UNI_PMED_ME_AC,UNI_PMED_SE_AC AS CF_UNI_PMED_SE_AC,
	UNI_PMED_AN_AC AS CF_UNI_PMED_AN_AC,UNI_TRA_AN_AC AS CF_UNI_TRA_AN_AC,UNI_TRA_AN_AN AS CF_UNI_TRA_AN_AN,UNI_TRA_DI_AC AS CF_UNI_TRA_DI_AC,UNI_TRA_DI_AN AS CF_UNI_TRA_DI_AN,UNI_TRA_ME_AC AS CF_UNI_TRA_ME_AC,
	UNI_TRA_ME_AN AS CF_UNI_TRA_ME_AN,UNI_TRA_ULT_TR AS CF_UNI_TRA_ULT_TR,UNI_TRA_SE_AC AS CF_UNI_TRA_SE_AC,UNI_TRA_SE_AN AS CF_UNI_TRA_SE_AN,UNI_TRA_SN_AC AS CF_UNI_TRA_SN_AC,UNI_TRA_SN_AN AS CF_UNI_TRA_SN_AN,
	UTI_12_M AS CF_UTI_12_M,UTI_NUM_MES AS CF_UTI_NUM_MES,TIPO_FONDO AS CF_TIPO_FONDO,AUT_OPE_SIMUL AS CF_AUT_OPE_SIMUL,NEMO_DCV AS CF_NEMO_DCV,

	SOC.RUT_ADMIN AS SOC_RUT_ADMIN, SOC.NOM_ADMIN AS SOC_NOM_ADMIN, COALESCE(INVC.PRESEN_AJU,0) AS CF_PRESEN_AJU, SOC.RUT AS SOC_RUT

FROM TBRVMI RV
INNER JOIN  TBCFMI CF ON RV.NEMO = CF.NEMO AND RV.MERCADO = 'CF'
LEFT JOIN TBINVC INVC ON RV.NEMO = INVC.NEMO
LEFT JOIN TBASSOC SOC ON SOC.NEMO_SASA = CF.NEMO_SASA AND RTRIM(LTRIM(SOC.NEMO)) = RTRIM(LTRIM(CF.NEMO))-- AND SOC.TIPO = 'F'
ORDER BY RV.NEMO
